        _lang() {
            var l = (window.mySimulation && window.mySimulation.lang) || 'en';
            return l;
        }

        _L(round) {
            var l = this._lang();
            return round[l] || round.en;
        }

        _t(key, vars) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                return window.mySimulation.t(key, vars);
            }
            return key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 1400,
                    ebitda: 287,
                    margin: 20.5,
                    capitalRemaining: 37,
                    aiTrustScore: 50,
                    governanceScore: 0,
                    revenueHistory: [],
                    ebitdaHistory: [],
                    trustHistory: [],
                    governanceHistory: [],
                    eventTriggered: [],
                    roundScores: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: 'B',
                    decision2: 'B',
                    decision3: 'B',
                    decision4: 'B',
                    decision5: 'B'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var d1 = document.getElementById('decision1Input');
            var d2 = document.getElementById('decision2Input');
            var d3 = document.getElementById('decision3Input');
            var d4 = document.getElementById('decision4Input');
            var d5 = document.getElementById('decision5Input');
            if (d1) decisions.decision1 = d1.value;
            if (d2) decisions.decision2 = d2.value;
            if (d3) decisions.decision3 = d3.value;
            if (d4) decisions.decision4 = d4.value;
            if (d5) decisions.decision5 = d5.value;
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var optionScores = { A: 0, B: 1, C: 2, D: 3 };
            var choices = [d.decision1, d.decision2, d.decision3, d.decision4, d.decision5];

            var avgAggressiveness = choices.reduce(function(sum, c) { return sum + (optionScores[c] || 1); }, 0) / 5;

            var dominantChoice = 'B';
            var counts = { A: 0, B: 0, C: 0, D: 0 };
            choices.forEach(function(c) { counts[c] = (counts[c] || 0) + 1; });
            var maxCount = 0;
            Object.keys(counts).forEach(function(k) {
                if (counts[k] > maxCount) { maxCount = counts[k]; dominantChoice = k; }
            });

            var fin = round.financials[dominantChoice];

            var eventHappened = false;
            if (round.eventProb > 0 && Math.random() < round.eventProb) {
                eventHappened = true;
            }

            var revenueImpact = fin.revenue;
            var costImpact = fin.govCost;
            var riskCost = fin.riskPenalty;

            if (eventHappened) {
                riskCost += fin.eventPenalty;
            }

            var netEbitdaImpact = revenueImpact - costImpact - riskCost;

            var govInvestment = 0;
            if (d.decision5 === 'A') govInvestment = roundIdx === 0 ? 5 : roundIdx === 1 ? 1.2 : roundIdx === 4 ? Math.max(ds.capitalRemaining * 0.6, 2) : 0.8;
            else if (d.decision5 === 'B') govInvestment = roundIdx === 0 ? 3 : roundIdx === 1 ? 0.6 : roundIdx === 4 ? Math.max(ds.capitalRemaining * 0.4, 1) : 0.5;
            else if (d.decision5 === 'C') govInvestment = roundIdx === 0 ? 1.5 : roundIdx === 1 ? 0.15 : roundIdx === 4 ? Math.max(ds.capitalRemaining * 0.25, 0.5) : 0.3;
            else govInvestment = roundIdx === 0 ? 0.5 : roundIdx === 1 ? 0 : roundIdx === 4 ? Math.max(ds.capitalRemaining * 0.08, 0.2) : 0.1;

            ds.capitalRemaining = Math.max(0, ds.capitalRemaining - govInvestment);

            ds.ebitda = Math.round((ds.ebitda + netEbitdaImpact) * 100) / 100;
            ds.revenue = Math.round((ds.revenue + revenueImpact) * 100) / 100;
            ds.margin = Math.round((ds.ebitda / ds.revenue) * 1000) / 10;

            var trustDelta = 0;
            if (avgAggressiveness < 1) trustDelta = 8;
            else if (avgAggressiveness < 1.5) trustDelta = 5;
            else if (avgAggressiveness < 2.5) trustDelta = 2;
            else trustDelta = -3;

            if (eventHappened && avgAggressiveness < 1.5) trustDelta -= 5;
            if (eventHappened && avgAggressiveness >= 2) trustDelta += 3;

            ds.aiTrustScore = Math.max(0, Math.min(100, ds.aiTrustScore + trustDelta));

            var govDelta = 0;
            if (d.decision5 === 'A') govDelta = 20;
            else if (d.decision5 === 'B') govDelta = 14;
            else if (d.decision5 === 'C') govDelta = 8;
            else govDelta = 3;

            if (roundIdx === 4) {
                var coherenceBonus = 0;
                if (avgAggressiveness <= 1.2 || avgAggressiveness >= 2.8) coherenceBonus = 5;
                else if (avgAggressiveness <= 1.8 || avgAggressiveness >= 2.2) coherenceBonus = 3;
                govDelta += coherenceBonus;
            }

            ds.governanceScore = Math.min(100, ds.governanceScore + govDelta);

            ds.revenueHistory.push(ds.revenue);
            ds.ebitdaHistory.push(ds.ebitda);
            ds.trustHistory.push(ds.aiTrustScore);
            ds.governanceHistory.push(ds.governanceScore);
            ds.eventTriggered.push(eventHappened);

            var roundScore = Math.round(netEbitdaImpact * 2 + govDelta + trustDelta);
            ds.roundScores.push(roundScore);

            // platform score: same three components getPerformanceSummary sums into totalScore, from current domainState, clamped 0 to 100
            var perfFinancialScore = Math.round(Math.max(-40, Math.min(40, ((ds.ebitda - 287) / 287) * 40)));
            var perfDecisionScore = Math.round(Math.min(30, ds.aiTrustScore * 0.3));
            var perfGovScore = Math.round(Math.min(30, ds.governanceScore * 0.3));
            var overallScore = Math.max(0, Math.min(100, perfFinancialScore + perfDecisionScore + perfGovScore));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: overallScore });

            var L = this._L(round);
            var resultsHtml = '<strong>' + L.title + '</strong>';
            resultsHtml += '<br>' + this._t('res_dominant', { opt: dominantChoice });
            resultsHtml += '<br>' + this._t('res_revenue', { v: revenueImpact.toFixed(1) });
            resultsHtml += '<br>' + this._t('res_net_ebitda', { v: netEbitdaImpact.toFixed(1) });
            resultsHtml += '<br>' + this._t('res_gov_invest', { v: govInvestment.toFixed(1) });
            if (eventHappened) {
                resultsHtml += '<br><strong>' + this._t('event_label') + ':</strong> ' + L.eventText;
            }

            var panel = document.getElementById('roundResultsPanel');
            var textEl = document.getElementById('roundResultsText');
            if (panel) panel.style.display = 'block';
            if (textEl) textEl.innerHTML = resultsHtml;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                dominantChoice: dominantChoice,
                revenueImpact: revenueImpact,
                netEbitdaImpact: netEbitdaImpact,
                govInvestment: govInvestment,
                eventTriggered: eventHappened,
                trustDelta: trustDelta,
                govDelta: govDelta,
                revenue: ds.revenue,
                ebitda: ds.ebitda,
                margin: ds.margin,
                capitalRemaining: ds.capitalRemaining,
                aiTrustScore: ds.aiTrustScore,
                governanceScore: ds.governanceScore
            };
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var L = this._L(round);

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = L.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = L.briefing;

            var aiRecEl = document.getElementById('aiRecommendation');
            var aiRecText = document.getElementById('aiRecText');
            var aiConf = document.getElementById('aiConfidence');
            if (aiRecEl && L.aiRec) {
                aiRecEl.style.display = 'block';
                if (aiRecText) aiRecText.innerHTML = L.aiRec;
                if (aiConf) aiConf.innerHTML = this._t('confidence_label') + ': ' + round.aiConfidence;
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) eventEl.style.display = 'none';

            for (var i = 0; i < 5; i++) {
                var dIdx = i + 1;
                var sel = document.getElementById('decision' + dIdx + 'Input');
                var lbl = document.getElementById('decision' + dIdx + 'Label');
                var desc = document.getElementById('decision' + dIdx + 'Desc');
                if (sel && L.decisions[i]) {
                    var prev = sel.value;
                    var opts = L.decisions[i].options;
                    sel.innerHTML = '';
                    Object.keys(opts).forEach(function(k) {
                        var opt = document.createElement('option');
                        opt.value = k;
                        opt.textContent = k + ': ' + opts[k];
                        sel.appendChild(opt);
                    });
                    if (opts[prev] !== undefined) sel.value = prev;
                    else sel.value = 'B';
                    if (lbl) lbl.textContent = L.decisions[i].label;
                    if (desc) desc.textContent = '';
                }
            }
        }

