        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastState = history[history.length - 1];
            var results = lastState.results || {};
            var pick = function(v, dflt) { return (v === undefined || v === null) ? dflt : v; };
            var finalRevenue = pick(results.revenue, 1400);
            var finalEbitda = pick(results.ebitda, 287);
            var finalMargin = pick(results.margin, 20.5);
            var finalTrust = pick(results.aiTrustScore, 50);
            var finalGov = pick(results.governanceScore, 0);

            var financialScore = Math.round(Math.max(-40, Math.min(40, ((finalEbitda - 287) / 287) * 40)));
            var decisionScore = Math.round(Math.min(30, finalTrust * 0.3));
            var govScore = Math.round(Math.min(30, finalGov * 0.3));
            var totalScore = financialScore + decisionScore + govScore;

            var performance = this._t('perf_developing');
            if (totalScore >= 70) performance = this._t('perf_excellent');
            else if (totalScore >= 50) performance = this._t('perf_strong');
            else if (totalScore >= 30) performance = this._t('perf_competent');

            var insights = [];
            if (finalGov >= 70) insights.push(this._t('insight_gov_high'));
            else if (finalGov < 40) insights.push(this._t('insight_gov_low'));
            if (finalTrust >= 70) insights.push(this._t('insight_trust_high'));
            else if (finalTrust < 35) insights.push(this._t('insight_trust_low'));
            if (finalMargin > 21) insights.push(this._t('insight_margin_high'));
            else if (finalMargin < 19) insights.push(this._t('insight_margin_low'));
            if (insights.length === 0) insights.push(this._t('insight_balanced'));

            return {
                financialScore: financialScore,
                decisionScore: decisionScore,
                governanceScore: govScore,
                totalScore: totalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.eventTriggered) return this._t('hint_event');
            if (state.domainState.capitalRemaining < 5 && state.currentPeriod < 5) return this._t('hint_capital');
            if (state.domainState.aiTrustScore < 30) return this._t('hint_trust_low');
            if (state.domainState.governanceScore < 20 && state.currentPeriod > 2) return this._t('hint_gov_low');
            if (results.netEbitdaImpact < -1) return this._t('hint_loss');
            return null;
        }

